170	        return this.householdSize;
171	    }
172	
173	    public void setHouseholdSize(Integer householdSize) {
174	        this.householdSize = householdSize;
175	    }
176	
177	    /**
178	     * The owner's membership level, a number from 1 to 3 derived at read time from stored fields.
179	     * Starts at 1; add 1 when an email is present; add 1 when {@link #getNamesakeCount() namesakeCount}
180	     * is 0; capped at 3 (level 4 is reserved for tenure).
181	     */
182	    @Transient
183	    public Integer getMembershipLevel() {
184	        int level = 1;
185	        boolean hasEmail = this.email != null && !this.email.isBlank();
186	        if (hasEmail) {
187	            level++;
188	        }
189	        if (this.namesakeCount != null && this.namesakeCount == 0) {
190	            level++;
191	        }
192	        return Math.min(level, 3);
193	    }
194	
195	    /**
196	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
197	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
198	     * ignored). {@code null} when the owner has no customerCode.
199	     */
200	    @Transient
201	    public Integer getCheckDigit() {
202	        if (this.customerCode == null) {
203	            return null;
204	        }
205	        int sum = 0;
206	        boolean dbl = true;
207	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
208	            char c = this.customerCode.charAt(i);
209	            if (c < '0' || c > '9') {
210	                continue;
211	            }
212	            int d = c - '0';
213	            if (dbl) {
214	                d *= 2;
215	                if (d > 9) {
216	                    d -= 9;
217	                }
218	            }
219	            sum += d;
220	            dbl = !dbl;
221	        }
222	        return (10 - (sum % 10)) % 10;
223	    }
224	
225	    /**
226	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
227	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
228	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
229	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
230	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
231	     * yields {@code 'UNKNOWN'}.
232	     */
233	    @Transient
234	    public String getLocality() {
235	        String byPostcode = regionForPostcode(this.postcode);
236	        if (byPostcode != null) {
237	            return byPostcode;
238	        }
239	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
240	    }
241	
242	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
243	    private static String regionForPostcode(String postcode) {
244	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
245	            return null;
246	        }
247	        int value = Integer.parseInt(postcode);
248	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
249	            int[] range = entry.getValue();
250	            if (value >= range[0] && value <= range[1]) {
251	                return entry.getKey();
252	            }
253	        }
254	        return null;
255	    }
256	
257	    /**
258	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
259	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
260	     */
261	    @Transient
262	    public String getContactPreference() {
263	        boolean hasEmail = this.email != null && !this.email.isBlank();
264	        return hasEmail ? "EMAIL" : "PHONE";
265	    }
266	
267	    /**
268	     * The single derived duplicate-detection key, {@code normalizedTelephone|email|householdId}
269	     * (the normalized telephone, the email or empty when absent, and the householdId or empty when
270	     * the owner has a unique household). All duplicate detection is expressed through this one key:
271	     * a create whose WHOLE identityKey equals an existing owner's is a duplicate. Because the
272	     * telephone is part of the key, two members of the same household with different telephones have
273	     * different identityKeys and are both allowed.
274	     */
275	    @Transient
276	    public String getIdentityKey() {
277	        String tel = this.telephone == null ? "" : this.telephone;
278	        String mail = (this.email == null || this.email.isBlank()) ? "" : this.email;
279	        String household = (this.householdId == null || this.householdId.isBlank()) ? "" : this.householdId;
280	        return tel + "|" + mail + "|" + household;
281	    }
282	
283	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
284	    private static final Map<String, String> CITY_REGION =
285	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
286	
287	    /** Region -> inclusive 4-digit postcode range {low, high}, preferred by {@link #getLocality()}. */
288	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
289	        "NSW", new int[] {2000, 2099},
290	        "VIC", new int[] {3000, 3099},
291	        "QLD", new int[] {4000, 4099});
292	
293	    protected Set<Pet> getPetsInternal() {
294	        if (this.pets == null) {
295	            this.pets = new HashSet<>();
296	        }
297	        return this.pets;
298	    }
299	
300	    protected void setPetsInternal(Set<Pet> pets) {
301	        this.pets = pets;
302	    }
303	
304	    public List<Pet> getPets() {
305	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
306	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
307	        return Collections.unmodifiableList(sortedPets);
308	    }
309	
310	    public void setPets(List<Pet> pets) {
311	        this.pets = new HashSet<>(pets);
312	    }
313	
314	    public void addPet(Pet pet) {
315	        getPetsInternal().add(pet);
316	        pet.setOwner(this);
317	    }
318	
319	    /**
320	     * Return the Pet with the given name, or null if none found for this Owner.
321	     *
322	     * @param name to test
323	     * @return true if pet name is already in use
324	     */
325	    public Pet getPet(String name) {
326	        return getPet(name, false);
327	    }
328	
329	    /**
330	     * Return the Pet with the given name, or null if none found for this Owner.
331	     *
332	     * @param name to test
333	     * @return true if pet name is already in use
334	     */
335	    public Pet getPet(String name, boolean ignoreNew) {
336	        name = name.toLowerCase();
337	        for (Pet pet : getPetsInternal()) {
338	            if (!ignoreNew || !pet.isNew()) {
339	                String compName = pet.getName();
340	                compName = compName.toLowerCase();
341	                if (compName.equals(name)) {
342	                    return pet;
343	                }
344	            }
345	        }
346	        return null;
347	    }
348	
349	    public Pet getPet(Integer petId) {
350	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
351	    }
352	
353	    @Override
354	    public String toString() {
355	        return new ToStringCreator(this)
356	
357	            .append("id", this.getId())
358	            .append("new", this.isNew())
359	            .append("lastName", this.getLastName())
360	            .append("firstName", this.getFirstName())
361	            .append("address", this.address)
362	            .append("city", this.city)
363	            .append("telephone", this.telephone)
364	            .toString();
365	    }
366	}
